SELECT *
FROM TB_FILE
WHERE 

		MENU_CD = #{menuCd}


		AND PK_ID = #{pkId}

ORDER BY REG_DT DESC

SELECT *
FROM TB_FILE
WHERE

		FILE_ID = #{fileId}


		AND MENU_CD = #{menuCd}


		AND PK_ID = #{pkId}

ORDER BY FILE_SEQ ASC ,REG_DT DESC

