, FILE_NEW_NAME
, FILE_NAME
, FILE_SIZE
, FILE_PATH
, FILE_TYPE
, FILE_EXTENSION
, FILE_SEQ
, REG_ID
, REG_DT)
VALUES ( #{pkId}
	   , #{fileDvCd}
       , #{menuCd}
       , #{fileNewName}
       , #{fileName}
       , #{fileSize}
       , #{filePath}
       , #{fileType}
       , #{fileExtension}
       , #{fileSeq}
       , #{regId}
       , now())
